window.MGProseData("9f4ab8697d51ae11bb0acb3ad5513222fbaa462339033bddb13f63ff7895fe78",{"html":"\u003cp>记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>r\u003c/mi>\u003c/munderover>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>s\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>r\u003c/mi>\u003c/munderover>\u003cmfrac>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>4.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nm=\\sum_{i=1}^r\\binom{n_i}{2},\\qquad s=m+d=\\sum_{i=1}^r\\frac{n_i(n_i+1)}2,\n\\qquad q_F=2,\\quad q_{K_\\mu}=4.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对每个块定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>否则\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\varepsilon_i(A)=\n\\sum_{\\substack{a\\in I_i\\\\ b\\notin I_i}}\n\\frac{(A_i)_{ba}}2\\pmod2\\in\\mathbb F_2,\n\\qquad\n\\chi_A=\n\\begin{cases}\n1,\u0026amp;\\varepsilon_1(A)=\\cdots=\\varepsilon_r(A)=0,\\\\\n0,\u0026amp;\\text{否则}.\n\\end{cases}\n\\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n求和中的条目均属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故此定义只使用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>三个域上的可行性完全相同：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003cmtext> \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\ \\mathscr S_L(A)\\ne\\varnothing\\iff\\chi_A=1.\\ }\n\\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n全部有限集合的基数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(3)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\ |\\mathscr R_{L,M}(A)|=\\chi_A\\,2^r q_L^{(M-1)m}\\quad(M\\ge2),\\ }\n\\tag{3}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n以及\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>r\u003c/mi>\u003c/msup>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(4)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n|\\mathscr C_{L,M}(A)|=\n\\begin{cases}\nq_L^s,\u0026amp;M=2,\\\\\n\\chi_A\\,2^r q_L^{(M-1)m+d},\u0026amp;M\\ge3.\n\\end{cases}}\n\\tag{4}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为空当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\chi_A=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 总不为空，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为空当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\chi_A=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>还有一个统一的、可直接核验的提升判准。给定\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar U\\in\\mathscr C_{L,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，任取其条目提升 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\\in M_d(\\mathcal O_L)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>d\u003c/mi>\u003c/munderover>\u003cmsubsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(5)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\bar U\\in\\mathscr R_{L,M}(A)\n\\iff\n\\sum_{k=1}^d u_{ka}^2\\equiv1\\pmod{2^{M+1}\\mathcal O_L}\n\\quad(1\\le a\\le d).\n}\n\\tag{5}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右端与提升的选择无关：改变一列中的条目 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M z\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其范数改变一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的量。\u003c/p>\n\u003cp>下面先证明这些公式，再给出固定点、约化映射与下降结论。\u003c/p>\n\u003chr>\n\u003cp>由每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可以构造一个规范投影 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_0=A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 开始迭代\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmi>B\u003c/mi>\u003cmi>t\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>I\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(6)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nB_{t+1}=B_t-(B_t^2-B_t)(2B_t-I)^{-1}.\n\\tag{6}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>B\u003c/mi>\u003cmi>t\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_t^2-B_t\\equiv0\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2B_t-I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可逆，迭代收敛到对称幂等矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nP_i\\equiv E_i\\pmod2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所有迭代项都是相应 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的收敛函数，所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 两两交换，并与全部 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 交换。\u003c/p>\n\u003cp>交换幂等矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_iP_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\\ne j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为零，因而为零。这里使用的简单事实是：若幂等矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T\\in2M_d(\\mathcal O_L)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T=T^k\\in2^kM_d(\\mathcal O_L)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。同理，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(7)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nP_iP_j=0\\ (i\\ne j),\\qquad \\sum_iP_i=I.\n\\tag{7}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">im\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{im}P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的图形基，其 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-坐标块恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_{n_i}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；具体可取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmo>:\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmsup>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX_i=P_i[:,I_i]\\bigl(P_i[I_i,I_i]\\bigr)^{-1}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n把这些列依次拼成 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsup>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(8)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nX\\equiv I\\pmod2,\\qquad\nP_iX=XE_i,\\qquad\nX^{\\mathsf T}X=\\operatorname{diag}(G_1,\\ldots,G_r),\n\\tag{8}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmi>X\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(9)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nG_i=X_i^{\\mathsf T}X_i=I_{n_i}+4B_i,\\qquad\nB_i=\\sum_{j\\ne i}(X_{ji}/2)^{\\mathsf T}(X_{ji}/2).\n\\tag{9}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmi>i\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(10)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nX_{ji}\\equiv A_i[I_j,I_i]\\pmod4\\quad(j\\ne i).\n\\tag{10}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n例如，由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i^2=P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可先得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i[I_i,I_i]\\equiv I\\pmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，再由\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[P_i,A_i]=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得到 (10)。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(11)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{tr}B_i\\equiv\\varepsilon_i(A)\\pmod2.\n\\tag{11}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>这个分解对有限精度的解也具有唯一性。事实上，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是真正解，或是模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的解，置\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>U\u003c/mi>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nQ_i=UE_iU^{\\mathsf T}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是与全部 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、因而与全部 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 交换的幂等矩阵，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q_i\\equiv E_i\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\\ne j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，幂等矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_iQ_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为零，所以为零；在有限商环上，同一论证使用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的幂零性。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Q\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q_i=P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>所以，在真正解和有限精度解两种情况下，分块条件都等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(12)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nU=X\\operatorname{diag}(V_1,\\ldots,V_r),\\qquad V_i\\equiv I\\pmod2,\n\\tag{12}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而正交条件分别成为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace width=\"1em\"/>\u003cmtext>或\u003c/mtext>\u003cmspace width=\"1em\"/>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(13)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nV_i^{\\mathsf T}G_iV_i=I\n\\quad\\text{或}\\quad\nV_i^{\\mathsf T}G_iV_i\\equiv I\\pmod{2^M}.\n\\tag{13}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>我们将反复使用以下提升事实：\u003c/p>\n\u003cblockquote>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的对称矩阵，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH\\equiv I\\pmod{2^M},\\qquad H_{aa}\\equiv1\\pmod{2^{M+1}},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Z\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z\\equiv I\\pmod{2^M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>Z\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>H\u003c/mi>\u003cmi>Z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Z^{\\mathsf T}HZ=I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003c/blockquote>\n\u003cp>证明如下。使用单位主元作 Gram–Schmidt 消元，可用一个模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的矩阵把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 化成对角阵\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{diag}(h_a)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。消元对对角条目的改变属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{2M}\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h_a\\in1+2^{M+1}\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h_a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都有平方根\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z_a\\in1+2^M\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，再作对角缩放即可。\u003c/p>\n\u003cp>这里使用的 Hensel 引理形式是：在完备离散赋值域上，若\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nv(f(a))\u0026gt;2v(f\u0026#x27;(a)),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则存在根 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>b\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v(b-a)\\ge v(f(a))-v(f\u0026#x27;(a))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>T\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(T)=T^2-h_a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>e\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e=v(2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>e\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>e\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nv(1-h_a)\\ge(M+1)e\u0026gt;2e,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故上述结论适用于三个域，并给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">z_a-1\\in2^M\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>先证明可行性的必要性；事实上，存在模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的解已足够。对一块写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>T\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V=I+2T\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_L/2\\mathcal O_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中记其像为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 (13) 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>t\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t^{\\mathsf T}=t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由对角范数模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(14)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n(B_i)_{aa}+t_{aa}+\\sum_k t_{ka}^2=0.\n\\tag{14}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 求和，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>a\u003c/mi>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(15)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{tr}B_i+\\sum_a(t_{aa}+t_{aa}^2)=0.\n\\tag{15}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在基域上，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t_{aa}+t_{aa}^2=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。在两个扩域上，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>ϵ\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>ϵ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>ϵ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(16)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\mathcal O_\\mu/2\\mathcal O_\\mu\n=\\mathbb F_2[\\epsilon]/(\\epsilon^2),\\qquad\n\\epsilon=\n\\begin{cases}\n1+\\theta_{-1},\u0026amp;\\mu=-1,\\\\\n\\theta_2,\u0026amp;\\mu=2.\n\\end{cases}\n\\tag{16}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ϵ\u003c/mi>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=x+\\epsilon y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>t\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>ϵ\u003c/mi>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t+t^2=\\epsilon y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以 (15) 的常数项仍强制\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{tr}B_i=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中。结合 (11)，得到必要性。\u003c/p>\n\u003cp>反过来，假设每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">tr\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{tr}B_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都为偶数。完全图的边到顶点次数的映射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmo>⟶\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003cmi>n\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathbb F_2^{\\binom n2}\\longrightarrow\\mathbb F_2^n\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n的像恰为坐标和为零的向量。因此，可选一个对称的整数矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\sum_{k\\ne a}(T_i)_{ka}\\equiv(B_i)_{aa}\\pmod2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i=I+2T_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i^{\\mathsf T}G_iV_i\\equiv I\\pmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且其对角条目模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。应用上述提升事实，得到有理整数环上的真正解 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_0\\in\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这证明 (2)，并给出构造 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的收敛算法。\u003c/p>\n\u003cp>可行时，所有真正解具体为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(17)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\mathscr S_L(A)=\nU_0\\left\\{\n\\operatorname{diag}(V_i):\nV_i^{\\mathsf T}V_i=I,\\quad V_i\\equiv I\\pmod2\n\\right\\}.\n}\n\\tag{17}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>同一个提升事实证明 (5)。必要性已显然。若右端成立，由规范分块可先把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 改成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>u\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nu\u0026#x27;=X\\operatorname{diag}(V_i)\\equiv u\\pmod{2^M}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其各块 Gram 矩阵模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，对角条目模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。逐块应用提升事实，便得到与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同类的真正解。\u003c/p>\n\u003cp>为计算基数，只须在 (17) 中计算每块的正交群。模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>T\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nV=I+2T.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n有限正交条件恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>t\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t^{\\mathsf T}=t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故有限解数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^{n(n+1)/2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。真正解的模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 像还须满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>t\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(18)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nt_{aa}+\\sum_k t_{ka}^2=0.\n\\tag{18}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上，对角有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个自由变量，非对角变量的次数须全为零；后者有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个独立条件。因此解数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^{n+\\binom n2-(n-1)}=2^{\\binom n2+1}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 (16) 的环上，写 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ϵ\u003c/mi>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t=x+\\epsilon y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。条件变为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的非对角次数为零，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">y_{aa}=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是解数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^{2\\binom n2+1}=2q_L^{\\binom n2}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两种情形统一为：每块的真正模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 像有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2q_L^{\\binom n2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 个元素。\u003c/p>\n\u003cp>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，精确正交群中模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的部分由 Cayley 变换\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>H\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>H\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsup>\u003cmi>H\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>H\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>H\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(19)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nV=(I-H)(I+H)^{-1},\\qquad\nH^{\\mathsf T}=-H,\\quad H\\in2^{M-1}M_n(\\mathcal O_L)\n\\tag{19}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n参数化。模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\equiv I-2H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故每升一层，真正约化像增加因子\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^{\\binom n2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这证明 (3)。\u003c/p>\n\u003cp>最后，对模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的有限正交群定义范数缺陷\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>ν\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>V\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>V\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(20)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\nu_M(V)=\n\\left(\\frac{(V^{\\mathsf T}V-I)_{aa}}{2^M}\\pmod2\\right)_a.\n\\tag{20}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这是到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>n\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\mathcal O_L/2)^n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的群同态，核由 (5) 给出。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，对角矩阵\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{diag}(1+2^{M-1}a_1,\\ldots,1+2^{M-1}a_n)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n的缺陷为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(a_1,\\ldots,a_n)\\bmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 (20) 满射。这给出因子 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，证明 (4)。\u003c/p>\n\u003chr>\n\u003cp>现在描述伽罗瓦固定点。以下把 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 矩阵按标准块嵌入，记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>⨁\u003c/mo>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>⨁\u003c/mo>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathcal T=\\bigoplus_i\\operatorname{Sym}_{n_i}(\\mathbb F_2),\\qquad\n\\mathcal A=\\bigoplus_i\\operatorname{Alt}_{n_i}(\\mathbb F_2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{Alt}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 表示对称且对角为零的矩阵；因此\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>dim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi mathvariant=\"script\">T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>dim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>m\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\dim\\mathcal T=s,\\qquad \\dim\\mathcal A=m.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\\in\\mathcal A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>deg\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>B\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(21)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n(\\deg B)_a=\\sum_k B_{ka}\\in\\mathbb F_2.\n\\tag{21}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>固定环中的矩阵有唯一表示\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>B\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(22)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\bar U=V+2^{M-1}\\theta_\\mu B,\n\\tag{22}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的有理矩阵，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\\in M_d(\\mathbb F_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因为对一个条目\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a+b\\theta_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，固定条件正是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>b\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2b\\equiv0\\pmod{2^M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch1>有限解的固定点始终有如下描述：\n[\n\\boxed{\n\\mathscr C_{K_\\mu,M}(A)^{\\sigma_\\mu}\u003c/h1>\n\u003ch1>\\left{\nV+2^{M-1}\\theta_\\mu B:\nV\\in\\mathscr C_{F,M}(A),\\ B\\in\\mathcal T\n\\right}.\n}\n\\tag{23}\n]\n真正解约化像的固定点，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，以及在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\mu,M)=(2,2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，为\n[\n\\boxed{\n\\mathscr R_{K_\\mu,M}(A)^{\\sigma_\\mu}\u003c/h1>\n\u003cp>\\left{\nV+2^{M-1}\\theta_\\mu B:\nV\\in\\mathscr R_{F,M}(A),\\ B\\in\\mathcal A\n\\right}.\n}\n\\tag{24}\n]\u003c/p>\n\u003ch1>唯一的例外是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K_{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\in\\mathscr C_{F,2}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，定义可核验的向量\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(25)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\eta(V)_a=\\frac{\\sum_kV_{ka}^2-1}{4}\\pmod2.\n\\tag{25}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则\n[\n\\boxed{\n\\mathscr R_{K_{-1},2}(A)^{\\sigma_{-1}}\u003c/h1>\n\u003cp>\\left{\nV+2\\theta_{-1}B:\nV\\in\\mathscr C_{F,2}(A),\u003cbr>\nB\\in\\mathcal A,\u003cbr>\n\\eta(V)=\\deg B\n\\right}.\n}\n\\tag{26}\n]\n所以在这个例外中，固定矩阵类的有理部分 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 本身可能不属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,2}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>这些公式也精确说明了与基域集合的关系：取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 就分别得到基域上的\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并且它们正是固定点集中所有有理矩阵类。\u003c/p>\n\u003cp>证明 (23)—(26) 只需展开 (22)。其正交条件强制 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B^{\\mathsf T}=B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；分块条件的最高位只涉及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\bmod2=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从而强制 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 块对角。这给出 (23)。进一步，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>η\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\eta_M(V)_a=\\frac{\\sum_kV_{ka}^2-1}{2^M}\\pmod2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 (5)，属于真正约化像的条件恰为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>η\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi>μ\u003c/mi>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>k\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>于 \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(27)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\eta_M(V)_a+\\theta_\\mu B_{aa}\n+2^{M-2}\\mu\\sum_k B_{ka}=0\n\\quad\\text{于 }\\mathcal O_\\mu/2\\mathcal O_\\mu.\n\\tag{27}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 或 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，最后一项为零，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_{aa}=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>η\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta_M(V)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到 (24)。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2,\\mu=-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，得到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_{aa}=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>deg\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta(V)=\\deg B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即 (26)。\u003c/p>\n\u003cp>固定点数如下：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(28)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n|\\mathscr R_{K_\\mu,M}(A)^{\\sigma_\\mu}|\n=\\chi_A\\,2^{Mm+r}\\qquad(M\\ge2),\n}\n\\tag{28}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>s\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>d\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(29)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n|\\mathscr C_{K_\\mu,M}(A)^{\\sigma_\\mu}|=\n\\begin{cases}\n2^{2s},\u0026amp;M=2,\\\\\n\\chi_A\\,2^{Mm+2d+r},\u0026amp;M\\ge3.\n\\end{cases}}\n\\tag{29}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，所有模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的矩阵类都被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 固定，因此两个集合的伽罗瓦作用都平凡；这也验证了 (28) 在例外情形中的计数。\u003c/p>\n\u003ch1>所有轨道的长度为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 或 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，单点轨道就是上述固定点。轨道总数为\n[\n\\boxed{\n#\\bigl(\\mathscr R_{K_\\mu,M}/\\langle\\sigma_\\mu\\rangle\\bigr)\u003c/h1>\n\u003ch1>\\chi_A,2^{r-1}\n\\left(2^{2(M-1)m}+2^{Mm}\\right),\n}\n\\tag{30}\n]\n以及\n[\n\\boxed{\n#\\bigl(\\mathscr C_{K_\\mu,M}/\\langle\\sigma_\\mu\\rangle\\bigr)\u003c/h1>\n\u003cp>\\begin{cases}\n2^{2s},\u0026amp;M=2,\\\n\\chi_A,2^{r+2d-1}\n\\left(2^{2(M-1)m}+2^{Mm}\\right),\u0026amp;M\\ge3.\n\\end{cases}}\n\\tag{31}\n]\n双点轨道数相应为“总点数减固定点数”除以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003chr>\n\u003cp>精度约化的全部信息可以列在一个表中。表中的基域集合均按题意自然嵌入扩域集合。\u003c/p>\n\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>约化映射，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/th>\n\u003cth>约化像\u003c/th>\n\u003cth style=\"text-align:right\">每个非空纤维的大小\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M+1}\\to\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,M+1}\\to\\mathscr C_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>L\u003c/mi>\u003cmi>s\u003c/mi>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_L^s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{K_\\mu,M+1}^{\\sigma_\\mu}\\to\\mathscr R_{K_\\mu,M}^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>4\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4^m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{K_\\mu,M+1}^{\\sigma_\\mu}\\to\\mathscr C_{K_\\mu,M}^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:right\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>4\u003c/mn>\u003cmi>s\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4^s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003c/tbody>\n\u003c/table>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\chi_A=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，这些映射的定义域全部为空，因而没有非空纤维。\u003c/p>\n\u003cp>第一行由真正解的定义及 (19) 得到。第二行由 (5) 得到：多一层有限正交性正好提供所需的对角范数精度。对于后两行，下一层固定点的最高位项是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\\theta_\\mu B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，约化后消失；下一层精度至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以 (24)、(23) 及第二行分别给出像\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。反向包含可用基域上的真正解提升实现。\u003c/p>\n\u003cp>可行时，选定有理 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>U\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后，这些集合都是相应群的陪集，约化映射成为群同态。因此所有非空纤维等大；将 (3)、(4)、(28)、(29) 相除，恰得表中的大小。\u003c/p>\n\u003cp>真正解的固定点满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmtext> \u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(32)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\ \\mathscr S_{K_\\mu}(A)^{\\sigma_\\mu}=\\mathscr S_F(A).\\ }\n\\tag{32}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这是因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_\\mu^{\\sigma_\\mu}=\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\\mathcal O_\\mu\\cap\\mathbb Z_2=2\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>因而，对固定矩阵类 (22)：\u003c/p>\n\u003cul>\n\u003cli>若它属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{K_\\mu,M}^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则它能提升为一个真正的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-固定解，当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>若它属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{K_\\mu,M}^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则它能如此提升，当且仅当\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\in\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；后一个条件由 (5) 核验。\u003c/li>\n\u003c/ul>\n\u003cp>这也恰好刻画了哪些固定类能成为一条无限逐层相容的固定类序列在精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的分量。事实上，表中说明：有一个下一层固定提升，已经等价于属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；而基域真正解提供全部更高层。因此有自然双射\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">\u003cmunder accentunder=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">l\u003c/mi>\u003cmi mathvariant=\"normal\">i\u003c/mi>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">←\u003c/mo>\u003c/munder>\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmtext>  \u003c/mtext>\u003cmo>≅\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">\u003cmunder accentunder=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">l\u003c/mi>\u003cmi mathvariant=\"normal\">i\u003c/mi>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">←\u003c/mo>\u003c/munder>\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmtext>  \u003c/mtext>\u003cmo>≅\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(33)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\varprojlim_{M\\ge2}\\mathscr R_{K_\\mu,M}^{\\sigma_\\mu}\n\\;\\cong\\;\n\\varprojlim_{M\\ge2}\\mathscr C_{K_\\mu,M}^{\\sigma_\\mu}\n\\;\\cong\\;\\mathscr S_F(A).\n\\tag{33}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003chr>\n\u003cp>第 3 问的最优统一答案为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>2.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(34)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nN_{\\max}=\n\\begin{cases}\nM,\u0026amp;n_1=\\cdots=n_r=1,\\\\\nM-1,\u0026amp;\\max_i n_i\\ge2.\n\\end{cases}}\n\\tag{34}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 无关。\u003c/p>\n\u003cp>对给定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A,U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，把真正解唯一写成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>P\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>P\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nU=P+\\theta_\\mu Q,\\qquad P,Q\\in M_d(\\mathbb Z_2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n题设的有限固定条件等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\\in2^{M-1}M_d(\\mathbb Z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。能取满精度\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>N\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">N=M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的必要充分条件为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>U\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>U\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(35)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nQ\\in2^M M_d(\\mathbb Z_2)\n\\iff\n\\sigma_\\mu(U)\\equiv U\\pmod{2^{M+1}\\mathcal O_\\mu}.\n}\n\\tag{35}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n确实，若能与有理 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 相同，显然其 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-系数须被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整除。反之，若该系数消失，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\\bmod2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是一个有理的真正约化类，故由前述交集关系属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>证明统一下界：当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 (24)，固定的真正约化类为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>B\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>V\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nV+2^{M-1}\\theta_\\mu B,\\qquad V\\in\\mathscr R_{F,M}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取提升 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的有理真正解即可得到精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，扩域真正解的存在保证 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>χ\u003c/mi>\u003cmi>A\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\chi_A=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故有理真正解存在；两者均模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1=M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>如果全部 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n_i=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 (17)，每块的精确正交群只有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{1,-1\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此实际上\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(36)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\mathscr S_{K_\\mu}(A)=\\mathscr S_F(A),\n\\tag{36}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以能精确下降。\u003c/p>\n\u003cp>只要某块秩至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，下面的统一构造就在任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 给出最优性反例。取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_i=E_i,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并在该块的一个二维坐标平面上放置矩阵\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>h\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmi>h\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>h\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>h\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmi>h\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(37)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nR(h)=\\frac1{1+h^2}\n\\begin{pmatrix}\n1-h^2\u0026amp;-2h\\\\\n2h\u0026amp;1-h^2\n\\end{pmatrix},\n\\tag{37}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其余坐标取恒等。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>ρ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cmspace width=\"2em\"/>\u003cmi>h\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ρ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(38)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\rho_\\mu=\n\\begin{cases}\n1+\\theta_{-1},\u0026amp;\\mu=-1,\\\\\n\\theta_2,\u0026amp;\\mu=2,\n\\end{cases}\n\\qquad h=2^{M-2}\\rho_\\mu.\n\\tag{38}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在两种情况下，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>h\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h^2\\in2\\mathcal O_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以分母是单位，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R(h)^{\\mathsf T}R(h)=I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R(h)\\equiv I\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nJ=\\begin{pmatrix}0\u0026amp;1\\\\-1\u0026amp;0\\end{pmatrix}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>h\u003c/mi>\u003cmi>J\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>h\u003c/mi>\u003cmi>J\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">R(h)=(I-hJ)(I+hJ)^{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。两个 Cayley 变换之差是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2(h-k)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 乘以一个整矩阵，而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\sigma_\\mu(h)-h=-2^{M-1}\\theta_\\mu.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\sigma_\\mu(R(h))\\equiv R(h)\\pmod{2^M\\mathcal O_\\mu}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n另一方面，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>h\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>h\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mfrac>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>ρ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac{2h/(1+h^2)}{2^{M-1}}\\equiv\\rho_\\mu\\pmod{2\\mathcal O_\\mu}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右端的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-系数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以某个非对角条目的\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-系数恰被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、而不被 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 整除。这个真正解不能与任何有理矩阵模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 相同。构造 (37)—(38) 同时适用于两种扩张和全部精度，证明了 (34) 的最优性。\u003c/p>\n\u003cp>最后列出其余提升失败现象的实际例子。\u003c/p>\n\u003cp>取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r=2,n_1=n_2=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(39)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nA_1=\\begin{pmatrix}1\u0026amp;2\\\\2\u0026amp;0\\end{pmatrix},\n\\qquad\nA_2=I-A_1.\n\\tag{39}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它们满足全部输入条件，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_1=\\varepsilon_2=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以三个域上的真正解均不存在，模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的有限解也不存在。但\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(40)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\bar U=\\begin{pmatrix}1\u0026amp;2\\\\2\u0026amp;1\\end{pmatrix}\\pmod4\n\\tag{40}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n属于三个域的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：其 Gram 矩阵为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnspacing=\"0.2778em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>5\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>4\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>4\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>5\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left(\\begin{smallmatrix}5\u0026amp;4\\\\4\u0026amp;5\\end{smallmatrix}\\right)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且共轭后的两矩阵模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都是对角阵。它的列范数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故不属于任何 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。该例可嵌入任意两个不同的块，表明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时可行性确实可能失败；\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时判准自动成立。\u003c/p>\n\u003cp>在可行输入 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下，若某块至少二维，(40) 放在该块内便给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>∖\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{F,2}\\setminus\\mathscr R_{F,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对任意块秩、任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(41)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{diag}(1+2^{M-1},1,\\ldots,1)\\pmod{2^M}\n\\tag{41}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n属于每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，但其首列范数缺陷除以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为奇数，所以不属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>对任意块秩、任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(42)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{diag}(1+2^{M-1}\\theta_\\mu,1,\\ldots,1)\\pmod{2^M}\n\\tag{42}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{K_\\mu,M}^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，却既不是有理矩阵类，也不属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{K_\\mu,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。其范数缺陷除以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi>μ\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\theta_\\mu+2^{M-2}\\mu\\ne0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这给出了固定有限解不能提升为真正解、不能进入相容固定序列的统一例子。\u003c/p>\n\u003cp>构造 (37)—(38) 则给出固定的真正约化类不能提升为下一层固定类的统一例子。特别地，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>μ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mu=-1,M=2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h=1+\\theta_{-1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>R\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nR(h)\\equiv\n\\begin{pmatrix}\n1\u0026amp;2+2\\theta_{-1}\\\\\n2+2\\theta_{-1}\u0026amp;1\n\\end{pmatrix}\\pmod4.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它的有理部分正是 (40)，列范数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\\bmod8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故不属于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；而取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnspacing=\"0.2778em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B=\\left(\\begin{smallmatrix}0\u0026amp;1\\\\1\u0026amp;0\\end{smallmatrix}\\right)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，恰有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>deg\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta(V)=(1,1)=\\deg B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，实际实现了 (26) 中的特殊现象。\u003c/p>\n","source":"assets/content/9f4ab8697d51ae11bb0acb3ad5513222fbaa462339033bddb13f63ff7895fe78.html"});
